/*
 * A389642  Maximum word length generated by acyclic context-free grammar in
 *          Greibach normal form whose grammar size is at most n.
 * https://oeis.org/A389642
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 19, u16 n <= 39, u32 n <= 47, u64 n <= 47, u128 n <= 47,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A389642: a(n) = max_{1<=k<=n-2}(k * a(n-k-1)+1)
   Base values: a(1)=a(2)=1.
   For n>=21 the maximum is always attained at k=4, so a(n)=4*a(n-5)+1. */

#include <stdlib.h>
#include <stddef.h>

seq_t a(idx_t n)
{
    /* static cache holding computed values: cache[i] = a(i+1) */
    static seq_t *cache = NULL;
    static idx_t cache_size = 0;  /* current number of stored terms */

    /* Ensure space for at least indices 0..1 (a(1), a(2)) */
    if (cache_size < 2)
    {
        size_t needed = 2;
        seq_t *new_cache = (seq_t *)realloc(cache, needed * sizeof(seq_t));
        if (!new_cache && needed > 0)
            return 0;         /* allocation failure – value undefined */
        cache = new_cache;
        cache[0] = (seq_t)1;  /* a(1) */
        cache[1] = (seq_t)1;  /* a(2) */
        cache_size = 2;
    }

    /* Return cached value if already available */
    if (n <= cache_size)
        return cache[n-1];

    /* Allocate space for all terms up to n */
    if (cache_size < n)
    {
        size_t new_size = n;
        seq_t *new_cache = (seq_t *)realloc(cache, new_size * sizeof(seq_t));
        if (!new_cache && new_size > 0)
            return 0;        /* allocation failure – value undefined */
        cache = new_cache;

        /* Compute terms sequentially from cache_size+1 up to n */
        for (idx_t i = cache_size + 1; i <= n; ++i)
        {
            seq_t value;
            if (i <= 20)   /* use brute‑force recurrence for small indices */
            {
                seq_t best = (seq_t)0;
                for (idx_t k = 1; k <= i-2; ++k)
                {
                    /* a(i-k-1) is stored at cache[i-k-2] */
                    seq_t cand = (seq_t)k * cache[i-k-2] + (seq_t)1;
                    if (cand > best)
                        best = cand;
                }
                value = best;
            }
            else           /* for n >= 21 we use the closed recurrence */
            {
                /* a(i-5) is at cache[(i-5)-1] = cache[i-6] */
                value = (seq_t)4 * cache[i-6] + (seq_t)1;
            }
            cache[i-1] = value;
        }
        cache_size = n;
    }

    return cache[n-1];
}
